@SuppressFBWarnings({"ICAST_INTEGER_MULTIPLY_CAST_TO_LONG"}) public static long parseDateTime(CharSequence seq){
  try {
    int p=0;
    int year=Numbers.parseInt(seq,p,p+=4);
    checkChar(seq,p++,'-');
    int month=Numbers.parseInt(seq,p,p+=2);
    checkRange(month,1,12,"Month");
    checkChar(seq,p++,'-');
    boolean l=isLeapYear(year);
    int day=Numbers.parseInt(seq,p,p+=2);
    checkRange(day,1,getDaysPerMonth(month,l),"Day");
    checkChar(seq,p++,'T');
    int hour=Numbers.parseInt(seq,p,p+=2);
    checkRange(hour,0,23,"Hour");
    checkChar(seq,p++,':');
    int min=Numbers.parseInt(seq,p,p+=2);
    checkRange(min,0,59,"Minute");
    checkChar(seq,p++,':');
    int sec=Numbers.parseInt(seq,p,p+=2);
    checkRange(sec,0,59,"Second");
    int mil=0;
    if (seq.charAt(p) == '.') {
      mil=Numbers.parseInt(seq,++p,p+=3);
      checkRange(mil,0,999,"Millis");
    }
    if (p < seq.length()) {
      checkChar(seq,p,'Z');
    }
    return yearMillis(year,l) + monthOfYearMillis(month,l) + (day - 1) * DAY_MILLIS + hour * HOUR_MILLIS + min * MINUTE_MILLIS + sec * SECOND_MILLIS + mil;
  } catch (NumberFormatException | IndexOutOfBoundsException | NullPointerException e) {
    throw new IllegalArgumentException("Invalid date time format", e);
  }
}
